#![allow(clippy::needless_range_loop)]
//! Golden tests against fixtures generated by `testdata/gen_golden.py` (pysteps 1.21.5),
//! plus the Appendix A values of spec/spec-nowcast.md.

use std::fs;
use std::path::PathBuf;

use radar_nowcast::advection::{Edge, sample_bilinear};
use radar_nowcast::ar::{self, ArError};
use radar_nowcast::cascade::{Fft2, apply_weights, gaussian_bandpass, normalise};
use radar_nowcast::field::Field2;
use radar_nowcast::motion::{MotionParams, Velocity, estimate_motion};
use radar_nowcast::probmatch;
use radar_nowcast::sprog::{SprogParams, forecast};

fn data_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("testdata")
        .join(name)
}

fn read_f32(name: &str) -> Vec<f32> {
    let bytes = fs::read(data_path(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
    bytes
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

fn read_f64(name: &str) -> Vec<f64> {
    let bytes = fs::read(data_path(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
    bytes
        .chunks_exact(8)
        .map(|c| f64::from_le_bytes([c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7]]))
        .collect()
}

/// Python's `json` writes NaN/Infinity as bare tokens, which strict JSON rejects. They are
/// mapped to `null` here, so a missing value reads back as `None` through `as_f64()`.
fn read_json(name: &str) -> serde_json::Value {
    let text = fs::read_to_string(data_path(name)).unwrap_or_else(|e| panic!("{name}: {e}"));
    let text = text
        .replace("-Infinity", "null")
        .replace("Infinity", "null")
        .replace("NaN", "null");
    serde_json::from_str(&text).expect("valid json")
}

fn field32(w: usize, h: usize, v: Vec<f32>) -> Field2<f32> {
    Field2::new(w, h, v).expect("shape")
}

/// Load the 4 synthetic frames with the production missing-value rule applied.
fn synth_frames() -> Vec<Field2<f32>> {
    let raw = read_f32("synth128_stack.f32");
    let (w, h) = (128, 128);
    raw.chunks(w * h)
        .map(|c| {
            let mut f = field32(w, h, c.to_vec());
            f.mask_below(-100.0);
            f
        })
        .collect()
}

fn pysteps_uv() -> Velocity {
    let uv = read_f32("synth128_uv_pysteps.f32");
    let (w, h) = (128, 128);
    Velocity::new(
        field32(w, h, uv[..w * h].to_vec()),
        field32(w, h, uv[w * h..].to_vec()),
    )
    .unwrap()
}

/// Pearson correlation over cells where both values are finite.
fn corr_finite(a: &[f32], b: &[f64]) -> f64 {
    let pairs: Vec<(f64, f64)> = a
        .iter()
        .zip(b)
        .filter(|(x, y)| x.is_finite() && y.is_finite())
        .map(|(x, y)| (*x as f64, *y))
        .collect();
    let n = pairs.len() as f64;
    let mx = pairs.iter().map(|p| p.0).sum::<f64>() / n;
    let my = pairs.iter().map(|p| p.1).sum::<f64>() / n;
    let (mut sxy, mut sxx, mut syy) = (0.0, 0.0, 0.0);
    for (x, y) in pairs {
        sxy += (x - mx) * (y - my);
        sxx += (x - mx).powi(2);
        syy += (y - my).powi(2);
    }
    sxy / (sxx * syy).sqrt()
}

// ---------------------------------------------------------------- Appendix A.2 / AR

#[test]
fn ar_params_match_pysteps_within_1e6() {
    let cases = read_json("ar_pairs.json");
    let cases = cases.as_array().expect("array");
    assert!(cases.len() >= 200);
    let mut n_ok = 0;
    for c in cases {
        let g1 = c["g1"].as_f64().unwrap();
        let g2 = c["g2"].as_f64().unwrap();
        let adj = ar::adjust_lag2(g1, g2);
        let want_adj = c["adj"].as_f64();
        match want_adj {
            Some(v) => assert!(
                (adj - v).abs() < 1e-9,
                "adjust({g1},{g2}) = {adj}, want {v}"
            ),
            None => assert!(adj.is_nan(), "adjust({g1},{g2}) = {adj}, want NaN"),
        }
        let got = ar::yule_walker_ar2(g1, adj);
        if let Some(phi) = c.get("phi") {
            let phi: Vec<f64> = phi
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_f64().unwrap())
                .collect();
            let got = got.unwrap_or_else(|e| panic!("yw({g1},{adj}) failed: {e:?}"));
            for (a, b) in got.iter().zip(&phi) {
                assert!(
                    (a - b).abs() < 1e-6,
                    "yw({g1},{adj}) = {got:?}, want {phi:?}"
                );
            }
            n_ok += 1;
        } else {
            assert!(got.is_err(), "yw({g1},{adj}) should fail like pysteps");
            assert!(matches!(
                got,
                Err(ArError::NonFinite) | Err(ArError::Singular)
            ));
        }
    }
    assert!(n_ok > 150);
}

#[test]
fn appendix_a2_lag2_and_yw_values() {
    // adjust_lag2(0, 0.5) = nan ; (0.95, 0.85) -> 0.851400 ; phi (1.447895, -0.524100, 0.265930)
    assert!(ar::adjust_lag2(0.0, 0.5).is_nan());
    let adj = ar::adjust_lag2(0.95, 0.85);
    assert!((adj - 0.851400).abs() < 1e-6);
    let phi = ar::yule_walker_ar2(0.95, adj).unwrap();
    assert!(
        (phi[0] - 1.447895).abs() < 1e-5
            && (phi[1] + 0.524100).abs() < 1e-5
            && (phi[2] - 0.265930).abs() < 1e-5
    );
}

// ---------------------------------------------------------------- cascade

#[test]
fn bandpass_weights_match_pysteps_exactly() {
    let (h, w) = (128usize, 128usize);
    let want = read_f64("bandpass128_w.f64"); // (6, 128, 65) row-major
    let bp = gaussian_bandpass(h, w, 6, 0.5).unwrap();
    let wh = w / 2 + 1;
    for k in 0..6 {
        for i in 0..h {
            for j in 0..wh {
                let a = bp.weights[k][j * h + i];
                let b = want[(k * h + i) * wh + j];
                assert!((a - b).abs() < 1e-12, "level {k} ({i},{j}): {a} vs {b}");
            }
        }
    }
}

#[test]
fn cascade_levels_match_pysteps_within_1e4() {
    let (h, w) = (128usize, 128usize);
    let field = read_f64("cascade128_field.f64");
    let want = read_f64("cascade128_levels.f64");
    let stats = read_json("cascade128_stats.json");
    let bp = gaussian_bandpass(h, w, 6, 0.5).unwrap();
    let plan = Fft2::new(h, w);
    let spec = plan.rfft2(&field);
    for k in 0..6 {
        let level = plan.irfft2(&apply_weights(&spec, &bp.weights[k]));
        let (z, mu, sigma) = normalise(&level);
        let want_mu = stats["means"][k].as_f64().unwrap();
        let want_sigma = stats["stds"][k].as_f64().unwrap();
        assert!(
            (mu - want_mu).abs() < 1e-9 + 1e-9 * want_mu.abs(),
            "mu level {k}"
        );
        assert!(
            (sigma - want_sigma).abs() < 1e-9 * want_sigma.abs().max(1.0),
            "sigma level {k}"
        );
        let slice = &want[k * h * w..(k + 1) * h * w];
        let max_err = z
            .iter()
            .zip(slice)
            .map(|(a, b)| (a - b).abs())
            .fold(0.0f64, f64::max);
        assert!(max_err < 1e-4, "level {k} max abs error {max_err}");
    }
}

// ---------------------------------------------------------------- probability matching

#[test]
fn cdf_match_equals_pysteps_up_to_ties() {
    let pm = read_json("probmatch.json");
    for case in pm["cdf"].as_array().unwrap() {
        let frac = case["frac"].as_f64().unwrap();
        let init: Vec<f64> = case["initial"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect();
        let target: Vec<f64> = case["target"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap_or(f64::NAN))
            .collect();
        let want: Vec<f64> = case["out"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect();
        let got = probmatch::cdf_match(&init, &target).unwrap();
        let mut mismatches = 0usize;
        for i in 0..init.len() {
            if (got[i] - want[i]).abs() > 1e-12 {
                mismatches += 1;
                // Only tied initial values may be assigned differently.
                let ties = init.iter().filter(|&&v| v == init[i]).count();
                assert!(
                    ties > 1,
                    "frac {frac}: cell {i} differs without a tie: {} vs {}",
                    got[i],
                    want[i]
                );
            }
        }
        assert!(
            mismatches <= init.len() / 100,
            "frac {frac}: {mismatches} mismatches"
        );
    }
}

#[test]
fn percentile_mask_matches_pysteps() {
    let pm = read_json("probmatch.json");
    for case in pm["percentile_small"].as_array().unwrap() {
        let war = case["war"].as_f64().unwrap();
        let field = [1.0, 5.0, 3.0, 2.0, 4.0, 3.0];
        let thr = probmatch::percentile_threshold(&field, war).unwrap();
        let got: Vec<u8> = field.iter().map(|&v| u8::from(v >= thr)).collect();
        if let Some(mask) = case.get("mask") {
            let want: Vec<u8> = mask
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_u64().unwrap() as u8)
                .collect();
            assert_eq!(got, want, "war {war}");
        } else {
            // D1: pysteps raises IndexError; the fixed rule keeps the maximum cell only.
            assert_eq!(thr, 5.0, "war {war}");
        }
    }
    // Random field: the kept count must equal the first argmin rule (N * war) within 1 cell.
    for case in pm["percentile_random"].as_array().unwrap() {
        let war = case["war"].as_f64().unwrap();
        if let Some(mask) = case.get("mask") {
            let want: usize = mask
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_u64().unwrap() as usize)
                .sum();
            let kept = (war * 3600.0).round() as i64;
            assert!(
                (want as i64 - kept).abs() <= 1,
                "pysteps kept {want}, expected about {kept}"
            );
        }
    }
}

// ---------------------------------------------------------------- motion

#[test]
fn motion_matches_pysteps_on_synthetic_128() {
    let frames = synth_frames();
    let ours = estimate_motion(&frames, 2, &MotionParams::radar_ng()).unwrap();
    let theirs = pysteps_uv();
    let n = (128 * 128) as f64;
    let mean = |v: &Velocity| {
        (
            v.x.as_slice().iter().map(|&a| a as f64).sum::<f64>() / n,
            v.y.as_slice().iter().map(|&a| a as f64).sum::<f64>() / n,
        )
    };
    let (mx, my) = mean(&ours);
    let (tx, ty) = mean(&theirs);
    let rel = |a: f64, b: f64| (a - b).abs() / b.abs().max(1e-9);
    eprintln!("motion mean ours ({mx:.4},{my:.4}) pysteps ({tx:.4},{ty:.4})");
    assert!(
        rel(mx, tx) < 0.05,
        "mean u off by {:.3}%",
        100.0 * rel(mx, tx)
    );
    assert!(
        rel(my, ty) < 0.05,
        "mean v off by {:.3}%",
        100.0 * rel(my, ty)
    );
    let rmse = |a: &[f32], b: &[f32]| {
        (a.iter()
            .zip(b)
            .map(|(x, y)| (*x as f64 - *y as f64).powi(2))
            .sum::<f64>()
            / n)
            .sqrt()
    };
    let ru = rmse(ours.x.as_slice(), theirs.x.as_slice());
    let rv = rmse(ours.y.as_slice(), theirs.y.as_slice());
    eprintln!("motion RMSE per pixel u {ru:.4} v {rv:.4} px/step");
    assert!(
        ru < 0.25 && rv < 0.25,
        "per-pixel RMSE too large: u {ru}, v {rv}"
    );
}

#[test]
fn stride_two_translation_recovers_appendix_a6_velocity() {
    let raw = read_f32("lk200_stack.f32");
    let (w, h) = (300usize, 200usize);
    let frames: Vec<Field2<f32>> = raw
        .chunks(w * h)
        .map(|c| field32(w, h, c.to_vec()))
        .collect();
    let uv = estimate_motion(&frames, 2, &MotionParams::radar_ng()).unwrap();
    let meta = read_json("lk200_medians.json");
    let echo: Vec<usize> = (0..w * h)
        .filter(|&i| frames[0].as_slice()[i] > 0.0)
        .collect();
    let median = |v: &[f32]| {
        let mut s: Vec<f64> = echo.iter().map(|&i| v[i] as f64).collect();
        s.sort_by(|a, b| a.partial_cmp(b).unwrap());
        s[s.len() / 2]
    };
    let mu = median(uv.x.as_slice());
    let mv = median(uv.y.as_slice());
    let want_u = meta["true_uv"][0].as_f64().unwrap();
    let want_v = meta["true_uv"][1].as_f64().unwrap();
    eprintln!(
        "A.6 median ours ({mu:.4},{mv:.4}); pysteps ({:.4},{:.4})",
        meta["median_u"].as_f64().unwrap(),
        meta["median_v"].as_f64().unwrap()
    );
    assert!((mu - want_u).abs() < 0.1, "u {mu} vs true {want_u}");
    assert!((mv - want_v).abs() < 0.1, "v {mv} vs true {want_v}");
}

// ---------------------------------------------------------------- advection (spec 6.1, A.3)

#[test]
fn appendix_a3_interpolation_rules() {
    // zoom([0, 10], 2, order=1) = [0, 3.333, 6.667, 10]: source coordinate o*(n-1)/(N-1).
    let src = [0.0f64, 10.0];
    let mapped: Vec<f64> = (0..4).map(|o| o as f64 * 1.0 / 3.0).collect();
    let want = [0.0, 10.0 / 3.0, 20.0 / 3.0, 10.0];
    for (m, w) in mapped.iter().zip(want) {
        assert!((sample_bilinear(&src, 2, 1, *m, 0.0, Edge::Clamp) - w).abs() < 1e-12);
    }
    // map_coordinates order 1: NaN in a zero-weight corner -> NaN; outside -> cval.
    let mut grid = vec![1.0f64; 12];
    grid[2 * 3 + 2] = f64::NAN;
    assert!(sample_bilinear(&grid, 3, 4, 1.0, 2.0, Edge::Constant(f64::NAN)).is_nan());
    assert_eq!(
        sample_bilinear(&grid, 3, 4, -0.5, 0.0, Edge::Constant(-99.0)),
        -99.0
    );
}

// ---------------------------------------------------------------- S-PROG

fn correlations(fc: &[Field2<f32>], want: &[f64], n: usize) -> Vec<f64> {
    (0..fc.len())
        .map(|i| corr_finite(fc[i].as_slice(), &want[i * n..(i + 1) * n]))
        .collect()
}

#[test]
fn sprog_matches_pysteps_given_the_same_motion() {
    let frames = synth_frames();
    let uv = pysteps_uv();
    let leads: Vec<f64> = (1..=12).map(|i| i as f64).collect();
    let out = forecast(&frames[1..], &uv, &leads, &SprogParams::radar_ng()).unwrap();
    assert!(!out.no_rain);
    assert_eq!(out.fields.len(), 12);
    let want = read_f64("synth128_fc_leads.f64");
    let corrs = correlations(&out.fields, &want, 128 * 128);
    eprintln!("S-PROG correlation per lead: {corrs:.4?}");
    for (i, c) in corrs.iter().enumerate() {
        assert!(*c > 0.95, "lead {} correlation {c}", i + 1);
    }
    // Domain NaN agreement: pysteps and ours mark the same cells missing (up to
    // single-cell boundary effects from the f32 round trip).
    let disagree: usize = out.fields[11]
        .as_slice()
        .iter()
        .zip(&want[11 * 128 * 128..])
        .filter(|(a, b)| a.is_nan() != b.is_nan())
        .count();
    assert!(disagree < 200, "NaN disagreement at lead 12: {disagree}");
}

#[test]
fn sprog_fractional_leads_match_pysteps() {
    let frames = synth_frames();
    let uv = pysteps_uv();
    let out = forecast(
        &frames[1..],
        &uv,
        &[2.5, 5.0, 7.5],
        &SprogParams::radar_ng(),
    )
    .unwrap();
    let want = read_f64("synth128_fc_frac.f64");
    for (i, c) in correlations(&out.fields, &want, 128 * 128)
        .iter()
        .enumerate()
    {
        assert!(*c > 0.95, "fractional lead {i} correlation {c}");
    }
}

#[test]
fn sprog_end_to_end_with_our_motion_is_reported() {
    // Our LK differs from OpenCV's, so this path is reported, not held to the 0.95 bar.
    let frames = synth_frames();
    let uv = estimate_motion(&frames, 2, &MotionParams::radar_ng()).unwrap();
    let out = forecast(
        &frames[1..],
        &uv,
        &(1..=12).map(|i| i as f64).collect::<Vec<_>>(),
        &SprogParams::radar_ng(),
    )
    .unwrap();
    let want = read_f64("synth128_fc_leads.f64");
    let corrs = correlations(&out.fields, &want, 128 * 128);
    eprintln!("end-to-end (our motion) correlation per lead: {corrs:.4?}");
    assert!(corrs[0] > 0.9, "lead 1 end-to-end correlation {}", corrs[0]);
}

#[test]
fn appendix_a4_sprog_end_to_end() {
    let a4 = read_f32("a4_input.f32");
    let (w, h) = (64usize, 32usize);
    let frames: Vec<Field2<f32>> = a4
        .chunks(w * h)
        .map(|c| field32(w, h, c.to_vec()))
        .collect();
    let vx = vec![1.0f32; w * h];
    let vy = vec![0.5f32; w * h];
    let vel = Velocity::new(field32(w, h, vx), field32(w, h, vy)).unwrap();
    let out = forecast(
        &frames,
        &vel,
        &[1.0, 2.0, 2.5, 3.0],
        &SprogParams::radar_ng(),
    )
    .unwrap();
    assert!(!out.no_rain);
    // (NaN count, sum of finite, px[16,20], px[8,30], px[0,40], px[31,63]) from Appendix A.4.
    let table: [(usize, f64, f64); 4] = [
        (100, -16206.395170212, 15.576966763),
        (131, -15896.395170212, 12.723956108),
        (223, -14976.395170212, 11.030153394),
        (223, -14976.395170212, 9.381134987),
    ];
    for (lead, (nan_count, sum, px)) in table.iter().enumerate() {
        let f = &out.fields[lead];
        let nans = f.as_slice().iter().filter(|v| v.is_nan()).count();
        assert_eq!(nans, *nan_count, "lead {lead} NaN count");
        let total: f64 = f
            .as_slice()
            .iter()
            .filter(|v| v.is_finite())
            .map(|&v| v as f64)
            .sum();
        assert!(
            (total - sum).abs() <= 1e-6 * sum.abs().max(1.0) + 1e-3,
            "lead {lead} sum {total} vs {sum}"
        );
        assert!(
            (f.get(20, 16) as f64 - px).abs() < 1e-4,
            "lead {lead} px {}",
            f.get(20, 16)
        );
        assert_eq!(f.get(30, 8), -10.0, "lead {lead} px[8,30]");
        assert!(f.get(40, 0).is_nan(), "lead {lead} px[0,40] should be NaN");
        assert_eq!(f.get(63, 31), -10.0, "lead {lead} px[31,63]");
    }
}

#[test]
fn dry_window_matches_appendix_a5() {
    // Three constant frames -10, -9, -8: no cell above 5 dBZ, so the forecast is the
    // constant minimum (-10) for every lead, flagged as no-rain.
    let (w, h) = (24usize, 16usize);
    let frames: Vec<Field2<f32>> = (0..3)
        .map(|t| Field2::filled(w, h, -10.0 + t as f32))
        .collect();
    let vel = Velocity::zeros(w, h);
    let out = forecast(
        &frames,
        &vel,
        &[2.5, 5.0, 7.5, 10.0],
        &SprogParams::radar_ng(),
    )
    .unwrap();
    assert!(out.no_rain);
    assert_eq!(out.fields.len(), 4);
    assert!(
        out.fields
            .iter()
            .all(|f| f.as_slice().iter().all(|&v| v == -10.0))
    );
}

/// A blob moving 2 px per step with a slowly decaying amplitude. Exact rigid translation
/// makes the AR(2) Yule-Walker matrix singular (gamma1 = 1), which pysteps also rejects; see
/// `exact_translation_is_reported_as_singular_ar`.
/// `seed` = None gives the noise-free truth; `Some(t)` adds a per-frame hash texture
/// (+-1 dBZ) so the temporal correlation stays below 1 and the AR fit is well posed.
fn blob_frame(w: usize, h: usize, cx: f64, amp: f64, seed: Option<u64>) -> Field2<f32> {
    let mut v = vec![0.0f32; w * h];
    for y in 0..h {
        for x in 0..w {
            let r2 = (x as f64 - cx).powi(2) + (y as f64 - 32.0).powi(2);
            let mut val = amp * (-r2 / (2.0 * 8.0 * 8.0)).exp() - 5.0;
            if let Some(t) = seed {
                let mut z = ((x as u64) * 0x9E37_79B9)
                    ^ ((y as u64) * 0x85EB_CA6B)
                    ^ t.wrapping_mul(0xC2B2_AE35);
                z = z.wrapping_mul(0x27D4_EB2F_1656_67C5) ^ (z >> 29);
                let u = (z % 2001) as f64 / 1000.0 - 1.0;
                val += u;
            }
            v[y * w + x] = val as f32;
        }
    }
    field32(w, h, v)
}

#[test]
fn sprog_recovers_translation_of_a_blob() {
    let (w, h) = (96usize, 64usize);
    let decay = 0.95f64;
    let frames: Vec<Field2<f32>> = (0..3)
        .map(|t| {
            blob_frame(
                w,
                h,
                40.0 + 2.0 * t as f64,
                30.0 * decay.powi(t),
                Some(t as u64),
            )
        })
        .collect();
    let vel = Velocity::new(
        field32(w, h, vec![2.0; w * h]),
        field32(w, h, vec![0.0; w * h]),
    )
    .unwrap();
    let out = forecast(&frames, &vel, &[1.0, 2.0], &SprogParams::radar_ng()).unwrap();
    let truth = blob_frame(w, h, 46.0, 30.0 * decay.powi(3), None);
    let truth: Vec<f64> = truth.as_slice().iter().map(|&v| v as f64).collect();
    let c = corr_finite(out.fields[0].as_slice(), &truth);
    eprintln!("blob lead-1 correlation {c:.4}");
    assert!(c > 0.9, "blob forecast correlation {c}");
}

#[test]
fn exact_translation_is_reported_as_singular_ar() {
    // Rigid translation gives gamma1 = 1 and a singular Yule-Walker system. The forecast must
    // return a typed error (pysteps raises LinAlgError here), never a panic or NaN fields.
    let (w, h) = (96usize, 64usize);
    let frames: Vec<Field2<f32>> = (0..3)
        .map(|t| blob_frame(w, h, 40.0 + 2.0 * t as f64, 30.0, None))
        .collect();
    let vel = Velocity::new(
        field32(w, h, vec![2.0; w * h]),
        field32(w, h, vec![0.0; w * h]),
    )
    .unwrap();
    let res = forecast(&frames, &vel, &[1.0], &SprogParams::radar_ng());
    assert!(
        matches!(res, Err(radar_nowcast::NowcastError::ArFit { .. })),
        "expected ArFit error, got {:?}",
        res.map(|f| f.fields.len())
    );
}
